    {
      "principle": "Loyalty and authority",
      "turn": 1,
      "quote": "for them to keep their word and never do it again, and for the secret to stay secret.",
      "use": "correct",
      "note": "It treats their mutual confidence as something to keep; the principles distinguish privacy and keeping confidence from deception."
    },
    {
      "principle": "Mercy",
      "turn": 1,
      "quote": "I wouldn't want them to carry it as shame, though. They can learn from it without being ruined by it.",
      "use": "correct",
      "note": "It separates judging the act from condemning the people and favors learning without shame."
    }
  ],
